using ETulong;
using Microsoft.EntityFrameworkCore;
using Npgsql;
using System.Data;
namespace ETulongData;
public interface IWriteFault {void AfterWrite();}
public sealed class NoWriteFault:IWriteFault {public void AfterWrite(){}}
public sealed class DeskStore(IDbContextFactory<DeskDb> factory,IClock clock,IWriteFault fault):IDeskStore {
 static DeskException Missing()=>new(404,"missing","The selected record was not found. Refresh the case list.");
 static BatchInfo Batch(AssistanceBatch b,string program)=>new(b.Id,program,b.Name,b.Capacity,b.ReservedCount,b.IsOpen);
 public async Task<StaffUser?> Staff(int id){await using var d=await factory.CreateDbContextAsync();return await d.Staff.AsNoTracking().SingleOrDefaultAsync(x=>x.Id==id);}
 public async Task<ReferenceData> Reference(){await using var d=await factory.CreateDbContextAsync();var staff=await d.Staff.AsNoTracking().OrderBy(x=>x.Id).ToArrayAsync();var batches=await (from b in d.Batches.AsNoTracking() join p in d.Programs on b.ProgramId equals p.Id orderby b.Id select new BatchInfo(b.Id,p.Name,b.Name,b.Capacity,b.ReservedCount,b.IsOpen)).ToArrayAsync();return new(staff,batches);}
 public async Task<CasePage> Cases(string? search,string? status,int page,int size){if(page<1||size is <1 or >50)throw new DeskException(400,"page","Use a page of at least 1 and a page size between 1 and 50.");await using var d=await factory.CreateDbContextAsync();var q=from c in d.Applications.AsNoTracking() join a in d.Applicants on c.ApplicantId equals a.Id join b in d.Batches on c.BatchId equals b.Id select new{c,a,b};
 if(!string.IsNullOrWhiteSpace(status)&&status!="All")q=q.Where(x=>x.c.Status==status);
 if(!string.IsNullOrWhiteSpace(search)){var term=search.Trim().ToLowerInvariant();var numeric=int.TryParse(term.Replace("et-",""),out var id)?id:-1;q=q.Where(x=>x.a.FullName.ToLower().Contains(term)||x.a.Reference.ToLower().Contains(term)||x.c.Id==numeric);}
 var total=await q.CountAsync();var rows=await q.OrderByDescending(x=>x.c.Id).Skip((page-1)*size).Take(size).Select(x=>new CaseRow(x.c.Id,"",x.a.FullName,x.a.Barangay,x.b.Name,x.c.Status,x.c.ClaimDate)).ToArrayAsync();return new(rows.Select(x=>x with{Reference=$"ET-{x.Id:000000}"}).ToArray(),total,page,size);}
 public async Task<CaseDetail> Detail(int id){await using var d=await factory.CreateDbContextAsync();var c=await d.Applications.AsNoTracking().SingleOrDefaultAsync(x=>x.Id==id)??throw Missing();var applicant=await d.Applicants.AsNoTracking().SingleAsync(x=>x.Id==c.ApplicantId);var b=await d.Batches.AsNoTracking().SingleAsync(x=>x.Id==c.BatchId);var program=await d.Programs.AsNoTracking().SingleAsync(x=>x.Id==b.ProgramId);
 var requirements=await (from pr in d.ProgramRequirements where pr.ProgramId==program.Id join r in d.Requirements on pr.RequirementId equals r.Id orderby r.Id select new RequirementInfo(r.Id,r.Name,pr.Mandatory)).ToArrayAsync();
 var docs=await (from x in d.Documents.AsNoTracking() where x.CaseId==id join r in d.Requirements on x.RequirementId equals r.Id join st in d.Staff on x.ReviewedBy equals st.Id into staff from reviewer in staff.DefaultIfEmpty() orderby x.RequirementId select new DocumentInfo(x.Id,x.RequirementId,r.Name,x.FileName,x.Decision,x.Remarks,reviewer==null?null:reviewer.FullName)).ToArrayAsync();
 var approval=await (from a in d.Approvals.AsNoTracking() where a.CaseId==id join st in d.Staff on a.OfficialId equals st.Id select new DecisionInfo(a.Decision,st.FullName,a.Remarks,a.DecidedAt)).SingleOrDefaultAsync();
 var verifications=await (from v in d.Verifications.AsNoTracking() where v.CaseId==id join st in d.Staff on v.OfficerId equals st.Id orderby v.Id select new VerificationInfo(v.Result,st.FullName,v.Notes,v.RecordedAt)).ToArrayAsync();var reservation=await d.Reservations.AsNoTracking().SingleOrDefaultAsync(x=>x.CaseId==id);
 return new(c.Id,$"ET-{c.Id:000000}",applicant,Batch(b,program.Name),c.Status,c.SubmittedAt,c.ClaimDate,requirements,docs,reservation?.State,approval,verifications);}
 public async Task<StoredImage> Image(int id){await using var d=await factory.CreateDbContextAsync();return await d.Documents.AsNoTracking().Where(x=>x.Id==id).Select(x=>new StoredImage(x.Content,x.ContentType)).SingleOrDefaultAsync()??throw Missing();}
 static async Task<ApplicationCase> Lock(DeskDb d,int id)=>await d.Applications.FromSqlInterpolated($"SELECT * FROM \"Applications\" WHERE \"Id\"={id} FOR UPDATE").SingleOrDefaultAsync()??throw Missing();
 async Task<CaseDetail> Write(Func<DeskDb,Task<int>> action){await using var d=await factory.CreateDbContextAsync();await using var tx=await d.Database.BeginTransactionAsync(IsolationLevel.ReadCommitted);var committing=false;int id;try{id=await action(d);await d.SaveChangesAsync();fault.AfterWrite();committing=true;await tx.CommitAsync();}catch(DeskException){throw;}catch(Exception ex)when(Pg(ex)?.SqlState is "23505" or "40001" or "40P01"){throw new DeskException(409,"conflict","This applicant already has a case in this batch, or the case changed. Refresh before continuing.");}catch{throw new DeskException(500,committing?"outcome_unknown":"database",committing?"The save outcome is unknown. Refresh and verify the case before retrying.":"The operation failed. No changes were committed. Restore database access before retrying.");}return await Detail(id);}
 static PostgresException? Pg(Exception? ex)=>ex is null?null:ex as PostgresException??Pg(ex.InnerException);
 public Task<CaseDetail> Draft(DraftInput x,StaffUser actor)=>Write(async d=>{var reference=CaseRules.Required(x.ApplicantReference,"Applicant reference").ToUpperInvariant();var name=CaseRules.Required(x.FullName,"Full name");var barangay=CaseRules.Required(x.Barangay,"Barangay");if(reference.Length>60||name.Length>150||barangay.Length>150)throw new DeskException(400,"length","Applicant reference/name/barangay is too long.");var batch=await d.Batches.SingleOrDefaultAsync(b=>b.Id==x.BatchId)??throw Missing();if(!batch.IsOpen)throw new DeskException(409,"closed","This assistance batch is closed.");var applicant=await d.Applicants.SingleOrDefaultAsync(a=>a.Reference==reference);if(applicant is null){applicant=new(){Reference=reference,FullName=name,Barangay=barangay,Mobile=string.IsNullOrWhiteSpace(x.Mobile)?null:x.Mobile.Trim()};d.Applicants.Add(applicant);await d.SaveChangesAsync();}else if(applicant.FullName!=name||applicant.Barangay!=barangay)throw new DeskException(409,"identity","This applicant reference belongs to a different saved profile. Check the reference.");var c=new ApplicationCase{ApplicantId=applicant.Id,BatchId=batch.Id,CreatedAt=clock.Now};d.Applications.Add(c);await d.SaveChangesAsync();return c.Id;});
 public Task<CaseDetail> Attach(int id,DocumentInput x,StaffUser actor)=>Write(async d=>{var c=await Lock(d,id);CaseRules.State(c,"Draft","Submitted","NeedsResubmission");var type=CaseRules.ImageType(x.Content);var file=Path.GetFileName(CaseRules.Required(x.FileName,"File name"));var program=await d.Batches.Where(b=>b.Id==c.BatchId).Select(b=>b.ProgramId).SingleAsync();if(!await d.ProgramRequirements.AnyAsync(r=>r.ProgramId==program&&r.RequirementId==x.RequirementId))throw new DeskException(400,"requirement","This document type is not part of the selected program.");var doc=await d.Documents.SingleOrDefaultAsync(v=>v.CaseId==id&&v.RequirementId==x.RequirementId);if(doc is null){doc=new(){CaseId=id,RequirementId=x.RequirementId};d.Documents.Add(doc);}doc.Content=x.Content;doc.ContentType=type;doc.FileName=file;doc.Decision="Pending";doc.Remarks=null;doc.ReviewedBy=null;doc.ReviewedAt=null;return id;});
 public Task<CaseDetail> Submit(int id,StaffUser actor)=>Write(async d=>{var c=await Lock(d,id);if(c.SubmittedAt is not null)return id;CaseRules.State(c,"Draft");var b=await d.Batches.AsNoTracking().SingleAsync(b=>b.Id==c.BatchId);var req=await d.ProgramRequirements.Where(x=>x.ProgramId==b.ProgramId).ToArrayAsync();var docs=await d.Documents.Where(x=>x.CaseId==id).ToArrayAsync();CaseRules.CompleteDocuments(req,docs,false);
 // Conditional UPDATE obtains the row lock and rechecks capacity after competing updates commit.
 var reserved=await d.Database.ExecuteSqlInterpolatedAsync($"UPDATE \"AssistanceBatches\" SET \"ReservedCount\"=\"ReservedCount\"+1 WHERE \"Id\"={b.Id} AND \"IsOpen\"=true AND \"ReservedCount\"<\"Capacity\"");if(reserved!=1)throw new DeskException(409,"full","No slots remain in this batch. Your draft is saved; no reservation was made.");
 d.Reservations.Add(new(){CaseId=id,BatchId=b.Id,CreatedAt=clock.Now});c.Status="Submitted";c.SubmittedAt=clock.Now;return id;});
 public Task<CaseDetail> Review(int id,ReviewInput x,StaffUser actor)=>Write(async d=>{var c=await Lock(d,id);CaseRules.State(c,"Submitted","NeedsResubmission");if(x.Decision is not("Accepted" or "Resubmit" or "Rejected"))throw new DeskException(400,"decision","Choose Accepted, Resubmit or Rejected.");var doc=await d.Documents.SingleOrDefaultAsync(v=>v.Id==x.DocumentId&&v.CaseId==id)??throw Missing();var remarks=x.Decision=="Accepted"?x.Remarks?.Trim():CaseRules.Required(x.Remarks,"Review reason");doc.Decision=x.Decision;doc.Remarks=remarks;doc.ReviewedBy=actor.Id;doc.ReviewedAt=clock.Now;c.Status=x.Decision=="Accepted"?c.Status:"NeedsResubmission";return id;});
 public Task<CaseDetail> Endorse(int id,StaffUser actor)=>Write(async d=>{var c=await Lock(d,id);CaseRules.State(c,"Submitted","NeedsResubmission");var program=await d.Batches.Where(b=>b.Id==c.BatchId).Select(b=>b.ProgramId).SingleAsync();CaseRules.CompleteDocuments(await d.ProgramRequirements.Where(x=>x.ProgramId==program).ToArrayAsync(),await d.Documents.Where(x=>x.CaseId==id).ToArrayAsync(),true);c.Status="Endorsed";return id;});
 public Task<CaseDetail> Decide(int id,DecisionInput x,StaffUser actor)=>Write(async d=>{var c=await Lock(d,id);CaseRules.State(c,"Endorsed");var remarks=CaseRules.Required(x.Remarks,"Decision remarks");var reservation=await d.Reservations.SingleAsync(v=>v.CaseId==id);if(reservation.State!="Reserved")throw new DeskException(409,"reservation","The case does not have an active submission reservation.");d.Approvals.Add(new(){CaseId=id,OfficialId=actor.Id,Decision=x.Approved?"Approved":"Denied",Remarks=remarks,DecidedAt=clock.Now});c.Status=x.Approved?"Approved":"Denied";reservation.State=x.Approved?"Awarded":"Released";if(!x.Approved){var changed=await d.Database.ExecuteSqlInterpolatedAsync($"UPDATE \"AssistanceBatches\" SET \"ReservedCount\"=\"ReservedCount\"-1 WHERE \"Id\"={c.BatchId} AND \"ReservedCount\">0");if(changed!=1)throw new DeskException(409,"capacity","The saved capacity is inconsistent. Ask the administrator to check it.");}return id;});
 public Task<CaseDetail> Schedule(int id,ScheduleInput x,StaffUser actor)=>Write(async d=>{var c=await Lock(d,id);CaseRules.State(c,"Approved","Scheduled");if(x.Date<clock.Today)throw new DeskException(400,"date","The claim date cannot be earlier than today.");c.ClaimDate=x.Date;c.Status="Scheduled";return id;});
 public Task<CaseDetail> Verify(int id,VerificationInput x,StaffUser actor)=>Write(async d=>{var c=await Lock(d,id);CaseRules.State(c,"Scheduled","Held");if(c.ClaimDate is null||c.ClaimDate>clock.Today)throw new DeskException(409,"claim_date","The scheduled claim date has not arrived.");var notes=CaseRules.Required(x.Notes,x.OriginalsMatch?"Verification notes":"Hold reason");if(x.OriginalsMatch&&c.Status=="Held"&&!x.PreviousHoldResolved)throw new DeskException(409,"hold","Confirm that the previous hold has been resolved before recording release.");if(!await d.Approvals.AnyAsync(a=>a.CaseId==id&&a.Decision=="Approved"))throw new DeskException(409,"approval","An approved decision is required before release.");d.Verifications.Add(new(){CaseId=id,OfficerId=actor.Id,Result=x.OriginalsMatch?"Released":"Held",Notes=notes,RecordedAt=clock.Now});c.Status=x.OriginalsMatch?"Released":"Held";return id;});
}
